.bullwhip-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e6edf3;
    background: linear-gradient(170deg, #0b1d2a 0%, #0f2a3a 55%, #12303f 100%);
    border-radius: 18px;
}

.bullwhip-container * {
    box-sizing: border-box;
}

.bullwhip-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #07151f 0%, #0e3346 55%, #0a4d4a 100%);
    color: #eafaf7;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(0, 0, 0, 0.45);
    border: 1px solid rgba(45, 212, 191, 0.18);
}

.bullwhip-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.bullwhip-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffce6b;
    background: rgba(255, 206, 107, 0.12);
    border: 1px solid rgba(255, 206, 107, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
}

.bullwhip-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #b9d4d6;
}

.bullwhip-chain {
    display: flex;
    align-items: stretch;
    gap: 6px;
    margin-bottom: 18px;
}

.bullwhip-tier {
    flex: 1;
    background: #112c3b;
    border-radius: 12px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-bottom: 4px solid #2dd4bf;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.bullwhip-tier-factory { border-bottom-color: #ef5350; }
.bullwhip-tier-dc { border-bottom-color: #ff8f00; }
.bullwhip-tier-wholesaler { border-bottom-color: #ffd54f; }
.bullwhip-tier-retail { border-bottom-color: #2dd4bf; }

.bullwhip-tier-name {
    font-weight: 800;
    font-size: 0.92rem;
    color: #eafaf7;
}

.bullwhip-tier-var {
    font-size: 0.8rem;
    font-weight: 700;
    color: #9fb6bd;
    font-variant-numeric: tabular-nums;
}

.bullwhip-tier-factory .bullwhip-tier-var { color: #ff8a85; }
.bullwhip-tier-dc .bullwhip-tier-var { color: #ffb74d; }
.bullwhip-tier-wholesaler .bullwhip-tier-var { color: #ffe082; }
.bullwhip-tier-retail .bullwhip-tier-var { color: #5eead4; }

.bullwhip-tier-arrow {
    align-self: center;
    font-size: 1.1rem;
    font-weight: 800;
    color: #4b7c8b;
}

.bullwhip-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #a9c2c9;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.bullwhip-period-counter #currentDay,
.bullwhip-period-counter #maxPeriods {
    font-weight: 800;
    color: #2dd4bf;
}

.bullwhip-round-name {
    background: rgba(45, 212, 191, 0.16);
    color: #5eead4;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.bullwhip-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffce6b;
    background: rgba(255, 206, 107, 0.12);
    border: 1px solid rgba(255, 206, 107, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.bullwhip-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.bullwhip-status-card {
    background: #102734;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.30);
    border-top: 4px solid #2dd4bf;
}

.bullwhip-card-variance { border-top-color: #ef5350; }
.bullwhip-card-cost { border-top-color: #ff8f00; }
.bullwhip-card-service { border-top-color: #2dd4bf; }
.bullwhip-card-mape { border-top-color: #5b8def; }

.bullwhip-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8da6ad;
}

.bullwhip-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.bullwhip-card-variance .bullwhip-value { color: #ff8a85; }
.bullwhip-card-cost .bullwhip-value { color: #ffb74d; }
.bullwhip-card-service .bullwhip-value { color: #5eead4; }
.bullwhip-card-mape .bullwhip-value { color: #8fb4ff; }

.bullwhip-sublabel {
    font-size: 0.74rem;
    color: #7f99a0;
    line-height: 1.35;
}

.bullwhip-card-variance.bullwhip-good .bullwhip-value { color: #5eead4; }
.bullwhip-card-variance.bullwhip-good { border-top-color: #2dd4bf; }
.bullwhip-card-cost.bullwhip-good .bullwhip-value { color: #5eead4; }
.bullwhip-card-cost.bullwhip-good { border-top-color: #2dd4bf; }
.bullwhip-card-service.bullwhip-bad .bullwhip-value { color: #ff8a85; }
.bullwhip-card-service.bullwhip-bad { border-top-color: #ef5350; }
.bullwhip-card-mape.bullwhip-good .bullwhip-value { color: #5eead4; }
.bullwhip-card-mape.bullwhip-good { border-top-color: #2dd4bf; }

.bullwhip-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #102734;
    border: 1px solid rgba(255, 206, 107, 0.28);
    color: #a9c2c9;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.bullwhip-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ffce6b;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.bullwhip-budget-bar.bullwhip-budget-over #budgetDisplay { color: #ff5b54; }

.bullwhip-briefing {
    display: flex;
    gap: 14px;
    background: #102734;
    border-left: 5px solid #2dd4bf;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.28);
}

.bullwhip-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.bullwhip-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.bullwhip-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c4d8db;
}

.bullwhip-briefing-text strong { color: #5eead4; }
.bullwhip-briefing-text em { color: #ffce6b; font-style: italic; }

.bullwhip-controls {
    background: #102734;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.28);
}

.bullwhip-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid rgba(255, 255, 255, 0.10);
    padding-bottom: 8px;
}

.bullwhip-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d4e3e6;
    margin: 14px 0 6px;
}

.bullwhip-container select,
.bullwhip-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2c4a59;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0c1f2b;
    color: #eafaf7;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.bullwhip-container select:focus,
.bullwhip-container input[type="number"]:focus {
    outline: none;
    border-color: #2dd4bf;
    box-shadow: 0 0 0 3px rgba(45, 212, 191, 0.18);
}

.bullwhip-container select option {
    background-color: #0c1f2b;
    color: #eafaf7;
}

.bullwhip-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2dd4bf;
}

.bullwhip-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #a9c2c9;
    margin-top: 4px;
}

.bullwhip-range-readout span:nth-child(2) {
    color: #2dd4bf;
    font-weight: 800;
}

.bullwhip-hint {
    font-size: 0.8rem;
    color: #7f99a0;
    margin-top: 8px;
    line-height: 1.4;
    font-style: italic;
}

.bullwhip-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.bullwhip-container .btn-primary {
    background: linear-gradient(135deg, #0a766e 0%, #2dd4bf 100%);
    border: none;
    color: #042b27;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(45, 212, 191, 0.28);
}

.bullwhip-container .btn-primary:hover {
    filter: brightness(1.08);
}

.bullwhip-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2c4a59;
    color: #a9c2c9;
    background: transparent;
}

.bullwhip-coach {
    background: linear-gradient(160deg, #07151f 0%, #0e2f40 100%);
    color: #d7ebe9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.34);
    border: 1px solid rgba(45, 212, 191, 0.14);
}

.bullwhip-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffce6b;
    margin-bottom: 8px;
}

.bullwhip-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.bullwhip-coach-body strong { color: #5eead4; }
.bullwhip-coach-body em { color: #ffce6b; font-style: italic; }

.bullwhip-history,
.bullwhip-chart {
    background: #102734;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.28);
}

.bullwhip-history h3,
.bullwhip-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #ffffff;
}

.bullwhip-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c4d8db;
}

.bullwhip-container table#usfHistoryTable th {
    background: #0c1f2b;
    color: #2dd4bf;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2c4a59;
}

.bullwhip-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    color: #c4d8db;
}

.bullwhip-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(255, 255, 255, 0.02);
}

.bullwhip-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .bullwhip-container {
        padding: 14px;
    }
    .bullwhip-header h1 {
        font-size: 1.7rem;
    }
    .bullwhip-chain {
        flex-direction: column;
    }
    .bullwhip-tier-arrow {
        transform: rotate(90deg);
    }
    .bullwhip-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .bullwhip-value {
        font-size: 2rem;
    }
    .bullwhip-clock {
        margin-left: 0;
    }
    .bullwhip-period-counter {
        font-size: 0.88rem;
    }
    .bullwhip-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .bullwhip-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.bw-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.bw-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.bw-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.bw-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.bw-cm-score strong { color: #4f9bd9; }
.bw-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.bw-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.bw-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.bw-cm-target.bw-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.bw-cm-target.bw-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.bw-cm-tick { font-weight: 700; }
.bw-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.bw-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.bw-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.bw-cm-metric strong { font-size: 16px; color: #eceff6; }
.bw-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.bw-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .bw-cm-metric { min-width: 70px; } .bw-cm-verdict { font-size: 19px; } }

