(function() {
    'use strict';

    class BullwhipBusterAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Bullwhip Buster`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Siam Pantry Co., Ltd. — THB).
            this.START_VARIANCE = 48;      // factory order variance ±48% (normal weeks)
            this.TARGET_VARIANCE = 18;     // good-practice target ≤±18%
            this.START_CARRYING = 55.8;    // THB M/year carrying cost at 9% cost of capital
            this.START_WRITEOFF = 31;      // THB M write-offs from the promotion
            this.START_COST = 86.8;        // THB M/year = carrying + write-offs baseline
            this.START_SERVICE = 89;       // % service (11% of outlets stocked out)
            this.TARGET_SERVICE = 96;      // % target service level
            this.START_MAPE = 38;          // % factory forecast error
            this.TARGET_MAPE = 15;         // % best-practice MAPE
            this.BUDGET_CAP = 18;          // THB M/year coordination & systems budget
            this.AVOIDABLE = 70;           // THB M/year avoidable cost if unaddressed
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    variance: this.START_VARIANCE,    // factory order variance (%)
                    cost: this.START_COST,            // inventory cost THB M/year
                    service: this.START_SERVICE,      // service level (%)
                    mape: this.START_MAPE,            // forecast error (%)
                    budget: 0,                        // THB M committed so far
                    overBudget: false,                // blew past the ฿18M cap
                    sharesPos: false,                 // POS / shared signal in place
                    smoothed: false,                  // an order-smoothing rule chosen
                    overSmoothed: false,              // smoothed so hard it went deaf to a surge
                    deepPromo: true,                  // still running deep periodic promos
                    partnerDark: true,                // big wholesaler not sharing data
                    inventoryFix: false,              // tried to fix with safety stock
                    varianceHistory: [this.START_VARIANCE],
                    costHistory: [this.START_COST],
                    serviceHistory: [this.START_SERVICE],
                    mapeHistory: [this.START_MAPE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic COMMON ERRORS so a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    amplifier: `retail`,
                    cause: `batching`,
                    fix: `safetystock`,
                    rigour: 35,
                    ordering: `reorder`,
                    info: `none`,
                    promo: `deep`,
                    invest: 2,
                    spike: `hold`,
                    leadtime: `ignore`,
                    partner: `assume`,
                    contingency: 40,
                    pitch: `inventory`,
                    deal: `demand`,
                    probe: `onekpi`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const am = document.getElementById(`amplifierInput`);
                const ca = document.getElementById(`causeInput`);
                const fx = document.getElementById(`fixInput`);
                const ri = document.getElementById(`rigourInput`);
                if (am) decisions.amplifier = am.value;
                if (ca) decisions.cause = ca.value;
                if (fx) decisions.fix = fx.value;
                if (ri) decisions.rigour = parseInt(ri.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const or = document.getElementById(`orderingInput`);
                const inf = document.getElementById(`infoInput`);
                const pr = document.getElementById(`promoInput`);
                const iv = document.getElementById(`investInput`);
                if (or) decisions.ordering = or.value;
                if (inf) decisions.info = inf.value;
                if (pr) decisions.promo = pr.value;
                if (iv) decisions.invest = parseFloat(iv.value);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0) {
                    warn(`warn_invest_value`); return false;
                }
            } else if (round === 3) {
                const sp = document.getElementById(`spikeInput`);
                const lt = document.getElementById(`leadtimeInput`);
                const pa = document.getElementById(`partnerInput`);
                const co = document.getElementById(`contingencyInput`);
                if (sp) decisions.spike = sp.value;
                if (lt) decisions.leadtime = lt.value;
                if (pa) decisions.partner = pa.value;
                if (co) decisions.contingency = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.contingency) || decisions.contingency < 0 || decisions.contingency > 100) {
                    warn(`warn_contingency_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const de = document.getElementById(`dealInput`);
                const pr = document.getElementById(`probeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (de) decisions.deal = de.value;
                if (pr) decisions.probe = pr.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Positive deltas reduce the bad KPIs (variance/cost/mape) and raise service.
            let varDelta = 0;       // change in factory order variance (%)
            let costDelta = 0;      // change in inventory cost (THB M/year)
            let serviceDelta = 0;   // change in service level (%)
            let mapeDelta = 0;      // change in forecast error (%)
            let spend = 0;          // THB M committed this round
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose. A correct read does not move KPIs much yet, but a wrong
                // read sets up the inventory trap and weak forecasting downstream.
                switch (d.amplifier) {
                    case `upstream`: mapeDelta -= 2; coachKey = `coach_r1_upstream`; break;
                    case `factory`: mapeDelta += 2; coachKey = `coach_r1_factory`; break;
                    case `retail`: mapeDelta += 3; coachKey = `coach_r1_retail`; break;
                    case `random`: mapeDelta += 4; coachKey = `coach_r1_random`; break;
                }

                switch (d.cause) {
                    case `signal`: mapeDelta -= 3; if (d.amplifier === `upstream`) coachKey = `coach_r1_sharp`; break;
                    case `batching`: mapeDelta += 1; coachKey = `coach_r1_batching`; break;
                    case `capacity`: mapeDelta += 2; coachKey = `coach_r1_capacity`; break;
                    case `suppliers`: mapeDelta += 2; coachKey = `coach_r1_suppliers`; break;
                }

                switch (d.fix) {
                    case `coordination`: varDelta += 1; break;
                    case `safetystock`: ds.inventoryFix = true; coachKey = `coach_r1_safetystock`; break;
                    case `capacity`: costDelta += 4; coachKey = `coach_r1_capacityfix`; break; // capex adds cost, doesn't fix amplification
                }

                // Rigour = quality of the cost-of-current-state diagnosis.
                if (d.rigour >= 60) { mapeDelta -= 2; }
                else if (d.rigour <= 25) { mapeDelta += 2; }

                summaryKey = (d.amplifier === `upstream` && d.cause === `signal` && d.fix === `coordination`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // The CORE design: ordering policy + information-sharing + promotion + budget.
                spend = d.invest;

                // (a) Ordering policy.
                switch (d.ordering) {
                    case `coordinated`: varDelta += 11; serviceDelta += 2; spend += 3; break;
                    case `smoothing`: varDelta += 9; ds.smoothed = true; spend += 1.5; break;
                    case `frequent`: varDelta += 5; costDelta += 2; spend += 1; break;
                    case `reorder`: varDelta -= 2; coachKey = `coach_r2_reorder`; break;
                }

                // (b) Information-sharing — the single most powerful countermeasure.
                switch (d.info) {
                    case `vmi`: varDelta += 12; mapeDelta += 12; serviceDelta += 4; costDelta += 18; spend += 8; ds.sharesPos = true; break;
                    case `forecast`: varDelta += 9; mapeDelta += 14; serviceDelta += 3; costDelta += 14; spend += 5; ds.sharesPos = true; break;
                    case `pos`: varDelta += 7; mapeDelta += 11; serviceDelta += 2; costDelta += 10; spend += 3; ds.sharesPos = true; break;
                    case `none`: varDelta -= 1; mapeDelta -= 1; ds.sharesPos = false; coachKey = `coach_r2_noinfo`; break;
                }

                // (c) Promotion & pricing policy.
                switch (d.promo) {
                    case `edlp`: varDelta += 6; serviceDelta += 1; ds.deepPromo = false; break;
                    case `scheduled`: varDelta += 4; serviceDelta += 1; ds.deepPromo = false; spend += 0.5; break;
                    case `deep`: varDelta -= 4; ds.deepPromo = true; coachKey = `coach_r2_deeppromo`; break;
                }

                // Smoothing WITHOUT information = decision tree #2 (policy without information).
                if (ds.smoothed && !ds.sharesPos) {
                    varDelta -= 3; mapeDelta -= 4; coachKey = `coach_r2_policyonly`;
                } else if (d.ordering === `coordinated` && ds.sharesPos && !ds.deepPromo) {
                    coachKey = `coach_r2_strong`;
                }

                // Budget accounting (decision tree #6 — over-spending).
                ds.budget = Math.round((ds.budget + spend) * 10) / 10;
                if (ds.budget > this.BUDGET_CAP) {
                    ds.overBudget = true;
                    // Over-budget designs get clawed back: a finance-forced de-scope blunts the gains.
                    const over = ds.budget - this.BUDGET_CAP;
                    varDelta -= Math.min(8, over * 1.2);
                    serviceDelta -= Math.min(3, over * 0.5);
                    coachKey = `coach_r2_overbudget`;
                }

                summaryKey = ds.overBudget ? `sum_r2_overbudget` :
                             (d.ordering === `coordinated` && ds.sharesPos && !ds.deepPromo) ? `sum_r2_good` :
                             (ds.smoothed && !ds.sharesPos) ? `sum_r2_policyonly` :
                             (ds.deepPromo ? `sum_r2_promo` : `sum_r2_weak`);
            } else if (round === 3) {
                // Stress-test the coordination against three live shocks.
                // (a) Viral demand surge — smooth noise without going deaf to signal.
                switch (d.spike) {
                    case `signal`: if (ds.sharesPos) { serviceDelta += 4; varDelta += 2; } else { serviceDelta += 1; } break;
                    case `hold`: serviceDelta -= 9; ds.overSmoothed = true; mapeDelta -= 4; coachKey = `coach_r3_oversmooth`; break;
                    case `rigid`: varDelta -= 9; serviceDelta -= 2; coachKey = `coach_r3_rigid`; break;
                }

                // (b) Lead-time disruption — targeted buffer, not panic, not denial.
                switch (d.leadtime) {
                    case `buffer`: serviceDelta += 3; costDelta += 2; varDelta += 1; break;
                    case `panic`: varDelta -= 8; costDelta += 12; coachKey = `coach_r3_panic`; break;
                    case `ignore`: serviceDelta -= 5; coachKey = `coach_r3_ignore`; break;
                }

                // (c) Non-cooperating wholesaler — assuming free POS visibility (decision tree #4).
                switch (d.partner) {
                    case `proxy`: varDelta += 5; mapeDelta += 5; serviceDelta += 2; spend += 2; ds.partnerDark = false; break;
                    case `drop`: varDelta -= 3; serviceDelta -= 2; coachKey = `coach_r3_drop`; break;
                    case `assume`: varDelta -= 6; serviceDelta -= 3; coachKey = `coach_r3_assume`; break;
                }

                // Contingency robustness — how much of the design survives incomplete info.
                if (d.contingency >= 60) { varDelta += 3; serviceDelta += 1; }
                else if (d.contingency <= 25) { varDelta -= 3; serviceDelta -= 2; }

                ds.budget = Math.round((ds.budget + spend) * 10) / 10;
                if (ds.budget > this.BUDGET_CAP) {
                    ds.overBudget = true;
                    const over = ds.budget - this.BUDGET_CAP;
                    varDelta -= Math.min(6, over * 1.2);
                    coachKey = `coach_r2_overbudget`;
                }

                if (d.spike === `signal` && d.leadtime === `buffer` && d.partner === `proxy` && !ds.overBudget) {
                    coachKey = `coach_r3_robust`;
                }

                summaryKey = (d.spike === `signal` && d.leadtime === `buffer` && d.partner === `proxy`) ? `sum_r3_good` :
                             (d.spike === `hold` ? `sum_r3_oversmooth` :
                             (d.partner === `assume` ? `sum_r3_assume` : `sum_r3_weak`));
            } else if (round === 4) {
                // Present the coordination strategy to the board & retail partner.
                switch (d.pitch) {
                    case `coordination`: varDelta += 4; costDelta += 4; serviceDelta += 2; mapeDelta += 3; coachKey = `coach_r4_coordination`; break;
                    case `inventory`: ds.inventoryFix = true; costDelta -= 8; serviceDelta -= 2; varDelta -= 3; coachKey = `coach_r4_inventory`; break;
                    case `speed`: varDelta -= 4; coachKey = `coach_r4_speed`; break;
                }

                switch (d.deal) {
                    case `mutual`: mapeDelta += 4; varDelta += 3; serviceDelta += 1; ds.partnerDark = false; break;
                    case `demand`: mapeDelta -= 2; coachKey = `coach_r4_demand`; break;
                    case `ignore`: mapeDelta -= 3; varDelta -= 2; coachKey = `coach_r4_ignoredeal`; break;
                }

                switch (d.probe) {
                    case `own`: serviceDelta += 1; varDelta += 2; if (d.pitch === `coordination`) coachKey = `coach_r4_own`; break;
                    case `onekpi`: coachKey = `coach_r4_onekpi`; break;
                    case `blame`: serviceDelta -= 1; coachKey = `coach_r4_blame`; break;
                }

                if (d.conviction >= 60) { varDelta += 2; }
                else if (d.conviction <= 25) { varDelta -= 2; }

                summaryKey = (d.pitch === `coordination` && d.deal === `mutual` && d.probe === `own`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- The inventory trap: if the learner keeps reaching for safety stock,
            // cost climbs and service still does NOT recover (decision tree #1). ----
            if (ds.inventoryFix) {
                costDelta -= 6;          // negative costDelta = cost goes UP (see sign below)
                serviceDelta -= 1;       // stock in the wrong place
            }

            // ---- Apply deltas. varDelta/costDelta/mapeDelta REDUCE the bad metric;
            // serviceDelta RAISES service. Clamp to sensible ranges. ----
            ds.variance = Math.max(6, Math.min(70, Math.round((ds.variance - varDelta) * 10) / 10));
            ds.cost = Math.max(38, Math.min(140, Math.round((ds.cost - costDelta) * 10) / 10));
            ds.service = Math.max(60, Math.min(99.5, Math.round((ds.service + serviceDelta) * 10) / 10));
            ds.mape = Math.max(10, Math.min(50, Math.round((ds.mape - mapeDelta) * 10) / 10));

            // Over-smoothing without a signal blinds the chain (decision tree #3).
            if (ds.overSmoothed && !ds.sharesPos) {
                ds.service = Math.min(ds.service, 84);
            }

            ds.varianceHistory.push(ds.variance);
            ds.costHistory.push(ds.cost);
            ds.serviceHistory.push(ds.service);
            ds.mapeHistory.push(ds.mape);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                variance: ds.variance,
                varDelta: Math.round(varDelta * 10) / 10,
                cost: ds.cost,
                costDelta: Math.round(costDelta * 10) / 10,
                service: ds.service,
                serviceDelta: Math.round(serviceDelta * 10) / 10,
                mape: ds.mape,
                mapeDelta: Math.round(mapeDelta * 10) / 10,
                budget: ds.budget,
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtVar(v) { return `±` + Math.round(Number(v)) + `%`; }
        _fmtCost(v) {
            const n = Math.round(Number(v) * 10) / 10;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = n.toFixed(1);
            return `฿` + (lang === `es` ? s.replace(`.`, `,`) : s) + `M`;
        }
        _fmtService(v) { return Math.round(Number(v) * 10) / 10 + `%`; }
        _fmtMape(v) { return Math.round(Number(v)) + `%`; }
        _fmtBudget(v) {
            const n = Math.round(Number(v) * 10) / 10;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = n.toFixed(1);
            return `฿` + (lang === `es` ? s.replace(`.`, `,`) : s) + `M / ฿` + this.BUDGET_CAP + `M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`varianceDisplay`, `domainState.variance`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.bullwhip-card-variance`);
                if (card) card.classList.toggle(`bullwhip-good`, n <= self.TARGET_VARIANCE);
                return self._fmtVar(n);
            });

            uiManager.bind(`costDisplay`, `domainState.cost`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.bullwhip-card-cost`);
                if (card) card.classList.toggle(`bullwhip-good`, n <= self.START_COST);
                return self._fmtCost(n);
            });

            uiManager.bind(`serviceDisplay`, `domainState.service`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.bullwhip-card-service`);
                if (card) card.classList.toggle(`bullwhip-bad`, n < 92);
                return self._fmtService(n);
            });

            uiManager.bind(`mapeDisplay`, `domainState.mape`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.bullwhip-card-mape`);
                if (card) card.classList.toggle(`bullwhip-good`, n <= 20);
                return self._fmtMape(n);
            });

            uiManager.bind(`budgetDisplay`, `domainState.budget`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.bullwhip-budget-bar`);
                if (bar) bar.classList.toggle(`bullwhip-budget-over`, n > self.BUDGET_CAP);
                return self._fmtBudget(n);
            });

            // Rigour slider readout.
            const ri = document.getElementById(`rigourInput`);
            const riReadout = document.getElementById(`rigourReadout`);
            if (ri && riReadout) {
                riReadout.textContent = ri.value;
                ri.addEventListener(`input`, function() { riReadout.textContent = ri.value; });
            }

            // Contingency slider readout.
            const co = document.getElementById(`contingencyInput`);
            const coReadout = document.getElementById(`contingencyReadout`);
            if (co && coReadout) {
                coReadout.textContent = co.value;
                co.addEventListener(`input`, function() { coReadout.textContent = co.value; });
            }
        }

        getChartConfig() {
            return {
                bullwhipChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Factory order variance (±%)`,
                                data: [],
                                borderColor: `#ef5350`,
                                backgroundColor: `rgba(239,83,80,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#ef5350`,
                                yAxisID: `y`
                            },
                            {
                                label: `Inventory cost (฿M/yr)`,
                                data: [],
                                borderColor: `#ff8f00`,
                                backgroundColor: `rgba(255,143,0,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#ff8f00`,
                                yAxisID: `y`
                            },
                            {
                                label: `Forecast error MAPE (%)`,
                                data: [],
                                borderColor: `#8fb4ff`,
                                backgroundColor: `rgba(143,180,255,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#8fb4ff`,
                                yAxisID: `y`
                            },
                            {
                                label: `Service level (%)`,
                                data: [],
                                borderColor: `#2dd4bf`,
                                backgroundColor: `rgba(45,212,191,0.10)`,
                                borderWidth: 2,
