                            legend: { position: `bottom`, labels: { color: `#a9c2c9`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 140, position: `left`,
                                ticks: { color: `#7f99a0` }, grid: { color: `rgba(255,255,255,0.06)` },
                                title: { display: true, text: `% · ฿M`, color: `#7f99a0` }
                            },
                            x: {
                                ticks: { color: `#7f99a0` }, grid: { color: `rgba(255,255,255,0.04)` },
                                title: { display: true, text: `Round`, color: `#7f99a0` }
                            }
