        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.varianceHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                bullwhipChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.varianceHistory.map((v) => Math.round(v)) },
                        { data: ds.costHistory.map((v) => Math.round(v)) },
                        { data: ds.mapeHistory.map((v) => Math.round(v)) },
                        { data: ds.serviceHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (KPI scoring + weights unchanged).
            const variance = Math.round(ds.variance);
            const cost = Math.round(ds.cost * 10) / 10;
            const service = Math.round(ds.service * 10) / 10;
            const mape = Math.round(ds.mape);
            const varScore = Math.max(0, Math.min(100, (this.START_VARIANCE - variance) / (this.START_VARIANCE - this.TARGET_VARIANCE) * 100));
            const realCostScore = Math.max(0, Math.min(100, (140 - cost) / (140 - 50) * 100));
            const serviceScore = Math.max(0, Math.min(100, (service - 80) / (this.TARGET_SERVICE - 80) * 100));
            const mapeScore = Math.max(0, Math.min(100, (this.START_MAPE - mape) / (this.START_MAPE - this.TARGET_MAPE) * 100));
            return Math.round(varScore * 0.32 + realCostScore * 0.20 + serviceScore * 0.26 + mapeScore * 0.22);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="bw-cm-target ' + (ok ? 'bw-cm-met' : 'bw-cm-missed') + '">'
                    + '<span class="bw-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.varianceTamed, t('tgt_variance'))
                + chip(!!summary.serviceMet, t('tgt_service'))
                + chip(!!summary.forecastFixed, t('tgt_forecast'))
                + chip(!!summary.costHeld, t('tgt_cost'))
                + chip(!!summary.withinBudget, t('tgt_budget'))
                + chip(!!summary.promoDisciplined, t('tgt_promo'));
            const fV = (typeof this._fmtVar === 'function') ? this._fmtVar(summary.variance != null ? summary.variance : 0) : ((summary.variance != null ? summary.variance : '-') + '%');
            const fC = (typeof this._fmtCost === 'function') ? this._fmtCost(summary.cost != null ? summary.cost : 0) : ('฿' + (summary.cost != null ? summary.cost : '-') + 'M');
            const fS = (typeof this._fmtService === 'function') ? this._fmtService(summary.service != null ? summary.service : 0) : ((summary.service != null ? summary.service : '-') + '%');
            const fM = (typeof this._fmtMape === 'function') ? this._fmtMape(summary.mape != null ? summary.mape : 0) : ((summary.mape != null ? summary.mape : '-') + '%');
            const metric = function (label, val) {
                return '<div class="bw-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const metrics = ''
                + metric(t('kpi_variance'), fV)
                + metric(t('kpi_cost'), fC)
                + metric(t('kpi_service'), fS)
                + metric(t('kpi_mape'), fM);
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="bw-cm">'
                +   '<div class="bw-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="bw-cm-verdict">' + verdict + '</div>'
                +   '<div class="bw-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="bw-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="bw-cm-targets">' + targets + '</div>'
                +   '<div class="bw-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="bw-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const variance = Math.round(ds.variance);
            const cost = Math.round(ds.cost * 10) / 10;
            const service = Math.round(ds.service * 10) / 10;
            const mape = Math.round(ds.mape);

            // v1.1.0 FIX A - composite delegated to _composite(ds) so the persisted per-round score
            // and this completion composite are identical by construction (KPI scoring/weights unchanged).
            const composite = this._composite(ds);

            const varianceTamed = variance <= this.TARGET_VARIANCE + 6;
            const costHeld = cost <= this.START_COST;
            const serviceMet = service >= 94;
            const forecastFixed = mape <= 22;
            const withinBudget = !ds.overBudget;
            // Promotion policy is a bullwhip ROOT CAUSE (concept §5 + decision tree #5):
            // keeping deep periodic discounts re-triggers the whipsaw no matter how well
            // the ordering/information plumbing was re-engineered. An undisciplined promo
            // therefore cannot earn the top verdict — the smooth chain whipsaws right back.
            const promoDisciplined = !ds.deepPromo;

            let pattern = `mixed`;
            if (ds.inventoryFix && cost > this.START_COST) pattern = `inventory`;
            else if (ds.smoothed && !ds.sharesPos) pattern = `policyonly`;
            else if (ds.overSmoothed && service < 88) pattern = `oversmooth`;
            else if (ds.partnerDark && variance > this.TARGET_VARIANCE + 10) pattern = `partner`;
            else if (ds.deepPromo && (variance > this.TARGET_VARIANCE + 8 || varianceTamed)) pattern = `promo`;
            else if (varianceTamed && serviceMet && forecastFixed && withinBudget) pattern = `coordinated`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_persists`;
            if (varianceTamed && serviceMet && forecastFixed && costHeld && withinBudget && promoDisciplined && composite >= 75) perfKey = `grade_busted`;
            else if (varianceTamed && serviceMet && withinBudget && promoDisciplined) perfKey = `grade_stabilised`;
            else if (ds.overBudget) perfKey = `grade_overbudget`;
            else if (pattern === `inventory`) perfKey = `grade_inventory`;
            else if (pattern === `oversmooth`) perfKey = `grade_oversmooth`;
            else if (pattern === `promo`) perfKey = `grade_promo`;
            else if (composite >= 55) perfKey = `grade_partial`;
            const performance = t(perfKey);

            const insights = [];
            if (perfKey === `grade_busted`) insights.push(window.mySimulation.t(`insight_busted`));
            else if (pattern === `inventory`) insights.push(window.mySimulation.t(`insight_inventory`));
            else if (pattern === `policyonly`) insights.push(window.mySimulation.t(`insight_policyonly`));
            else if (pattern === `oversmooth`) insights.push(window.mySimulation.t(`insight_oversmooth`));
            else if (pattern === `partner`) insights.push(window.mySimulation.t(`insight_partner`));
            else if (pattern === `promo`) insights.push(window.mySimulation.t(`insight_promo`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (!serviceMet) insights.push(window.mySimulation.t(`insight_service_low`));
            if (!forecastFixed) insights.push(window.mySimulation.t(`insight_mape_high`));
            if (varianceTamed && serviceMet && cost > this.START_COST) insights.push(window.mySimulation.t(`insight_cost_creep`));

            return {
                gradeKey: perfKey,
                score: composite,
                promoDisciplined: promoDisciplined,
                variance: variance,
                cost: cost,
                service: service,
                mape: mape,
                varianceTamed: varianceTamed,
                costHeld: costHeld,
                serviceMet: serviceMet,
                forecastFixed: forecastFixed,
                withinBudget: withinBudget,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.inventoryFix && ds.cost > this.START_COST) return window.mySimulation.t(`hint_inventory`);
            if (ds.smoothed && !ds.sharesPos) return window.mySimulation.t(`hint_policyonly`);
            if (ds.overSmoothed && ds.service < 88) return window.mySimulation.t(`hint_oversmooth`);
            if (ds.partnerDark && state.currentPeriod >= 3 && ds.variance > this.TARGET_VARIANCE + 10) return window.mySimulation.t(`hint_partner`);
            if (ds.deepPromo) return window.mySimulation.t(`hint_promo`);
            if (ds.variance <= this.TARGET_VARIANCE + 6 && ds.service >= 94 && ds.mape <= 22) return window.mySimulation.t(`hint_strong`);
            return null;
        }

